'use client'
import { LoadingSkeleton } from '@/components/ui/loading-skeleton'
import {reportError} from '@/modules/feedback/service'
import {useFeedbackError} from '@/modules/feedback/hooks'
import {errorFallbacks} from '@/modules/feedback/messages'
import {useEffect,useRef,useState} from 'react'
import type {PDFDocumentProxy,RenderTask} from 'pdfjs-dist'
import {action} from '../exercises/browser'
/** A viewer of the actual generated bytes, never a second document layout. */
export function PdfPreview({url,documentLabel="ficha de treinamento",regionLabel="Pré-visualização real da ficha em PDF"}:{url:string;documentLabel?:string;regionLabel?:string}){
 const canvas=useRef<HTMLCanvasElement>(null),container=useRef<HTMLDivElement>(null)
 const [pdf,setPdf]=useState<PDFDocumentProxy|null>(null),[page,setPage]=useState(1),[width,setWidth]=useState(0),[error,setError]=useFeedbackError(errorFallbacks.default),[revision,setRevision]=useState(0),[ready,setReady]=useState(false),[text,setText]=useState('')
 useEffect(()=>{const box=container.current;if(!box)return;let previous=0;const observer=new ResizeObserver(entries=>{const next=Math.floor(entries[0].contentRect.width);if(next!==previous){previous=next;setReady(false);setWidth(next)}});observer.observe(box);return()=>observer.disconnect()},[])
 useEffect(()=>{let live=true,task:ReturnType<typeof import('pdfjs-dist')['getDocument']>|undefined;const abort=new AbortController();void(async()=>{try{const response=await fetch(url,{cache:'no-store',signal:abort.signal});if(!response.ok){const body=await response.json();throw Error(body.message??'Prévia indisponível. Gere novamente.')}const data=new Uint8Array(await response.arrayBuffer()),viewer=await import('pdfjs-dist');viewer.GlobalWorkerOptions.workerSrc=new URL('pdfjs-dist/build/pdf.worker.min.mjs',import.meta.url).toString();if(!live)return;task=viewer.getDocument({data,enableXfa:false,useSystemFonts:false});const document=await task.promise;if(live)setPdf(document)}catch(e){if(live)setError(reportError(e,errorFallbacks.default))}})();return()=>{live=false;abort.abort();void task?.destroy()}},[url,revision,setError])
 useEffect(()=>{if(!pdf||width<1||!canvas.current)return;let live=true,render:RenderTask|undefined;const target=canvas.current;void(async()=>{try{const source=await pdf.getPage(page);if(!live)return;const viewport=source.getViewport({scale:Math.min(width,1200)/source.getViewport({scale:1}).width}),ratio=Math.min(window.devicePixelRatio||1,2);target.width=Math.floor(viewport.width*ratio);target.height=Math.floor(viewport.height*ratio);render=source.render({canvas:target,viewport,transform:ratio===1?undefined:[ratio,0,0,ratio,0,0]});await render.promise;const content=await source.getTextContent();if(live){setText(content.items.map(item=>'str'in item?item.str:'').join(' '));setReady(true)}}catch{if(live)setError('Não foi possível exibir esta página. Tente novamente ou baixe o PDF.')}})();return()=>{live=false;render?.cancel()}},[pdf,page,width,setError])
 return <div className="relative min-w-0 space-y-3" ref={container} role="region" aria-label={regionLabel}><div className="flex flex-wrap items-center gap-3"><button className={action} disabled={!pdf||page===1} onClick={()=>{setReady(false);setPage(n=>n-1)}}>Página anterior do PDF</button><span className="text-sm">{pdf?`Página ${page} de ${pdf.numPages}`:<LoadingSkeleton variant="inline" label="Carregando PDF…"/>}</span><button className={action} disabled={!pdf||page>=pdf.numPages} onClick={()=>{setReady(false);setPage(n=>n+1)}}>Próxima página do PDF</button></div>{error?<div role="alert" className="space-y-3"><p>{error}</p><button className={action} onClick={()=>{setError('');setPdf(null);setReady(false);setRevision(n=>n+1)}}>Tentar carregar prévia novamente</button></div>:<><p className="text-xs text-muted-foreground" role="status">{ready?'Página do PDF renderizada.':'Renderizando a prévia…'}</p><canvas ref={canvas} role="img" aria-label={'Página '+page+(documentLabel==='ficha de treinamento'?' da ficha de treinamento':' do '+documentLabel)} className="h-auto w-full rounded-lg bg-white"/><div className="sr-only" role="region" aria-label="Texto da página do PDF">{text}</div></>}</div>
}
